import{_ as a,c as r,o as t,a3 as i}from"./chunks/framework.BT-mtt1U.js";const f=JSON.parse('{"title":"Chat Groups","description":"","frontmatter":{"order":0,"title":"Chat Groups"},"headers":[],"relativePath":"wiki/chat/index.md","filePath":"wiki/chat/index.md","lastUpdated":null}'),n={name:"wiki/chat/index.md"};function o(s,e,l,h,c,d){return t(),r("div",null,e[0]||(e[0]=[i('<h1 id="chat-groups" tabindex="-1">Chat Groups <a class="header-anchor" href="#chat-groups" aria-label="Permalink to &quot;Chat Groups&quot;">​</a></h1><h2 id="general-etiquette" tabindex="-1">General Etiquette <a class="header-anchor" href="#general-etiquette" aria-label="Permalink to &quot;General Etiquette&quot;">​</a></h2><p>When participating in third-party chat groups, please adhere to the following guidelines:</p><ul><li>Be respectful and courteous.</li><li>Conduct prior research before asking questions.</li><li>Provide relevant device information when necessary.</li><li>Share logs using convenient formats, such as a Pastebin link.</li><li>Review notes, pinned messages, and other relevant information.</li></ul><h2 id="chat-groups-1" tabindex="-1">Chat Groups <a class="header-anchor" href="#chat-groups-1" aria-label="Permalink to &quot;Chat Groups&quot;">​</a></h2><h3 id="discord" tabindex="-1">Discord <a class="header-anchor" href="#discord" aria-label="Permalink to &quot;Discord&quot;">​</a></h3><ul><li><strong><a href="https://discord.gg/T5K2Wffug8" target="_blank" rel="noreferrer">Chat 1</a></strong>: General discussion group.</li><li><strong><a href="https://discord.gg/gYX6Dzz3pr" target="_blank" rel="noreferrer">Chat 2</a></strong>: Additional support community.</li></ul><h3 id="whatsapp" tabindex="-1">WhatsApp <a class="header-anchor" href="#whatsapp" aria-label="Permalink to &quot;WhatsApp&quot;">​</a></h3><ul><li><strong><a href="https://whatsapp.com/channel/0029VamKd7w3LdQV8AqlNF1h" target="_blank" rel="noreferrer">whatsapp channel</a></strong>: for nios updates.</li></ul><h3 id="telegram" tabindex="-1">Telegram <a class="header-anchor" href="#telegram" aria-label="Permalink to &quot;Telegram&quot;">​</a></h3><ul><li><strong><a href="https://t.me/NIOSUnofficial" target="_blank" rel="noreferrer">NIOS Students</a></strong>: General discussion group.</li><li><strong><a href="https://t.me/NEETNIOS" target="_blank" rel="noreferrer">NEET Students</a></strong>: For students preparing for NEET.</li><li><strong><a href="https://t.me/nios_freehelp_cs" target="_blank" rel="noreferrer">IT/Computer Subjects</a></strong>: For students studying IT-related or computer subjects.</li></ul><h3 id="reddit" tabindex="-1">Reddit <a class="header-anchor" href="#reddit" aria-label="Permalink to &quot;Reddit&quot;">​</a></h3><p>You can find posts from the NIOS community on Reddit here:<br><strong><a href="https://www.reddit.com/r/Nios_unofficial/" target="_blank" rel="noreferrer">Visit r/Nios_unofficial</a></strong></p><h2 id="official-nios-contact-information" tabindex="-1">Official NIOS Contact Information <a class="header-anchor" href="#official-nios-contact-information" aria-label="Permalink to &quot;Official NIOS Contact Information&quot;">​</a></h2><h3 id="email-addresses" tabindex="-1">Email Addresses <a class="header-anchor" href="#email-addresses" aria-label="Permalink to &quot;Email Addresses&quot;">​</a></h3><ul><li><strong>Admission-Related</strong>: <a href="mailto:dirsss@nios.ac.in" target="_blank" rel="noreferrer">dirsss@nios.ac.in</a></li><li><strong>Books and Study Materials</strong>: <a href="mailto:mpdd@nios.ac.in" target="_blank" rel="noreferrer">mpdd@nios.ac.in</a> or <a href="mailto:studymaterial@nios.ac.in" target="_blank" rel="noreferrer">studymaterial@nios.ac.in</a></li><li><strong>On-Demand Examination (ODE)</strong>: <a href="mailto:odes@nios.ac.in" target="_blank" rel="noreferrer">odes@nios.ac.in</a></li><li><strong>Results</strong>: <a href="mailto:rcell@nios.ac.in" target="_blank" rel="noreferrer">rcell@nios.ac.in</a></li><li><strong>Subject-Specific Questions</strong>: <a href="https://nios.ac.in/contact-us/ask-your-teacher.aspx" target="_blank" rel="noreferrer">Ask Your Teacher</a></li><li><strong>General Inquiries</strong>: <a href="mailto:lsc@nios.ac.in" target="_blank" rel="noreferrer">lsc@nios.ac.in</a></li><li><strong>Complaints and Feedback</strong>: <a href="mailto:cp@nios.ac.in" target="_blank" rel="noreferrer">cp@nios.ac.in</a></li><li><strong>Regional Centre Contacts</strong>: <a href="https://web.archive.org/web/20220216190435/https://sdmis.nios.ac.in/home/regional-center" target="_blank" rel="noreferrer">Regional Centre Archive</a></li></ul><h3 id="phone-numbers" tabindex="-1">Phone Numbers <a class="header-anchor" href="#phone-numbers" aria-label="Permalink to &quot;Phone Numbers&quot;">​</a></h3><ul><li><strong>Books and Study Materials</strong>: 8178547494</li><li><strong>General Inquiries</strong>: 1800-180-9393 (Toll-Free)</li></ul><h2 id="administrator-contact" tabindex="-1">Administrator Contact <a class="header-anchor" href="#administrator-contact" aria-label="Permalink to &quot;Administrator Contact&quot;">​</a></h2><ul><li><strong>Email</strong>: <a href="mailto:unofficialnios@gmail.com" target="_blank" rel="noreferrer">unofficialnios@gmail.com</a></li></ul>',20)]))}const g=a(n,[["render",o]]);export{f as __pageData,g as default};
